DAY_TO_BASE_MILESTONE = [
    0,   # day 0 (unused)
    0, 0, 1, 2, 2, 3, 3, 4, 4, 5,       # days 1-10 (Perkecambahan & Pembibitan Awal)
    5, 6, 6, 6, 7, 8, 9, 10, 10, 11,    # days 11-20 (Pindah Tanam & Vegetatif Aktif)
    11, 12, 12, 13, 13, 14, 14, 15, 15, 16, # days 21-30 (Vegetatif Lanjut & Roset Daun Sendok)
    16, 17, 17, 18, 18, 19, 20, 21, 22, 23  # days 31-40 (Pra-Panen Padat & Siap Panen Prima)
]

def get_plant_phase_key(dap_val: int) -> str:
    """Kategori fase botani standar budidaya pakcoy (1-40 HST)."""
    if dap_val <= 4:
        return "semai"
    elif dap_val <= 14:
        return "pembibitan"
    elif dap_val <= 28:
        return "vegetatif"
    elif dap_val <= 35:
        return "pra_panen"
    else:
        return "siap_panen"

def get_forecast_image_for_dap(target_dap: int, step_idx: int = 0, reload_seed: int = 0) -> str:
    """
    Mengambil foto visualisasi kondisi tanaman pakcoy yang tepat
    sesuai hari proyeksi fisiologis (HST 1-40), posisi kartu (0-3),
    dan seed putaran (reload_seed). Menjamin setiap kartu dalam 4 hari
    memperlihatkan pertumbuhan tanaman yang berkelanjutan (tanpa gambar kembar berdampingan).
    """
    card_idx = step_idx % 4
    current_dap = max(1, target_dap - (card_idx + 1))
    prev_m = -1
    card_milestone = 0
    for i in range(4):
        t_dap = min(max(current_dap + i + 1, 1), 40)
        raw_m = DAY_TO_BASE_MILESTONE[t_dap]
        m = max(raw_m, prev_m + 1)
        m = min(m, 23)
        if reload_seed > 0:
            m = (m + reload_seed) % 24
        if i == card_idx:
            card_milestone = m
            break
        prev_m = m
    return FORECAST_CHRONO_IMAGES[card_milestone]

